+            final int xMin = x * splits;
+            if (crossesDateline) {
+                return rightX > xMin || leftX < xMin + splits;
+            } else {
+                return rightX > xMin && leftX < xMin + splits;
+            }
+        }
+        return false;
+    }
+
+    /**
+     * Total number of tiles intersecting this bounds at the precision provided in the constructor.
+     */
+    public long getMaxTiles() {
+        return maxTiles;
+    }
