+        applyClusterState("add desired nodes", this::desiredNodesWithAllClusterNodes);
+
+        final var desiredNodes = DesiredNodes.latestFromClusterState(clusterService.state());
+
+        for (DesiredNode desiredNode : desiredNodes) {
