+                            node,
+                            MasterHistoryAction.NAME,
+                            new MasterHistoryAction.Request(),
+                            TransportRequestOptions.timeout(remoteMasterHistoryTimeout),
+                            new ActionListenerResponseHandler<>(ActionListener.runBefore(new ActionListener<>() {
